389	  // Mục 6 — hiệu ứng ban đêm khi bay dù (rút ngắn thời gian bằng config: SwiftShader chậm, dt bị chặn 0,05 s)
390	  {
391	    const G = await openApp(browser, srv.url + '?explore=glider');
392	    await frames(G.page, 3);
393	    check('6 ?test mặc định tắt bộ tự chạy', await G.page.evaluate(() => window.__app.explore.nightShows.enabled === false));
394	    await G.page.evaluate(() => {
395	      const a = window.__app, n = a.exFlight.CONFIG_explore.nightShows;
396	      n.swingSpeed = 600; n.swingRest = 0.2; a.explore.nightShows.enabled = true;
397	      window.__c = { starts: 0, closed: 0, blocked: 0, leftGlider: false };
398	      const c = a.songHan.ctrl, C = window.__c;
399	      c.addEventListener('swingStart', () => C.starts++);
400	      c.addEventListener('swingClosed', () => C.closed++);
401	      c.addEventListener('swingBlocked', () => C.blocked++);
402	      const watch = () => { if (a.cam.mode !== 'glider') C.leftGlider = true; requestAnimationFrame(watch); }; watch();
403	    });
404	    const setNight = (v) => G.page.evaluate((v) => { window.__app.dayNight.target = v; }, v);
405	    const until = (fn, name) => G.page.waitForFunction(fn, { timeout: 120000 }).then(() => check(name, true), () => check(name + ' (hết giờ)', false));
406	    const read = () => G.page.evaluate(() => { const a = window.__app; return { on: a.explore.nightShows.show.on, fire: a.explore.nightShows.show.fireOn, state: a.songHan.ctrl.state, ...window.__c }; });
407	
408	    await frames(G.page, 20);
409	    let r = await read();
410	    check('6a ngày: không phun, cầu đóng', !r.on && r.state === 'CLOSED' && r.starts === 0);
411	
412	    await setNight(1);
413	    await until(() => window.__app.explore.nightShows.show.fireOn, '6b đêm: có phun lửa');
414	    await until(() => window.__c.starts >= 2 && window.__c.closed >= 1, '6b đêm: cầu quay hết một lượt rồi quay lượt tiếp');
415	    const y0 = await G.page.evaluate(() => { const s = window.__app.explore.state, y = s.yaw; for (let i = 0; i < 30; i++) window.__app.explore.step(1 / 60, { turn: 1, climb: 0, throttle: 0 }); return s.yaw - y; });
416	    r = await read();
417	    check('6b vẫn lái được dù, không rời chế độ glider', y0 !== 0 && !r.leftGlider);
418	
419	    // 6c: giữ cầu ở OPEN (giả lập tàu chưa qua), chuyển sang ngày
420	    await G.page.evaluate(() => { const c = window.__app.songHan.ctrl; window.__cc = c.canClose; c.canClose = () => false; });
421	    await until(() => window.__app.songHan.ctrl.state === 'OPEN', '6c cầu đã mở');
422	    await setNight(0);
423	    await frames(G.page, 5);
424	    r = await read();
425	    check('6c sang ngày: dừng phun, cầu vẫn chờ tàu', !r.on && !r.fire && r.state === 'OPEN');
426	    await G.page.evaluate(() => { window.__app.songHan.ctrl.canClose = window.__cc; });
427	    await until(() => window.__app.songHan.ctrl.state === 'CLOSED', '6c tàu qua: cầu đóng');
428	    const s6c = (await read()).starts;
429	    await frames(G.page, 20);
430	    check('6c ban ngày không có lượt mới', (await read()).starts === s6c);
431	
432	    // 6d: bão chặn rồi hết
433	    await G.page.evaluate(() => { window.__app.songHan.ctrl.canStart = () => false; window.__c.blocked = 0; });
434	    await setNight(1);
435	    await frames(G.page, 20);
436	    r = await read();
437	    check('6d bão: không quay, không phát swingBlocked', r.state === 'CLOSED' && r.blocked === 0);
438	    await G.page.evaluate(() => { window.__app.songHan.ctrl.canStart = () => true; window.__c.starts = 0; });
439	    await until(() => window.__c.starts >= 1, '6d hết bão: quay lượt mới');
440	    await setNight(0);
441	    await until(() => window.__app.songHan.ctrl.state === 'CLOSED', '6d về trạng thái đóng');
442	
443	    // 6f: đang quay 1× khi đang bay thì tăng tốc và đóng xong
444	    await G.page.evaluate(() => { window.__app.songHan.ctrl.start(1); });
445	    await until(() => window.__app.songHan.ctrl.speed === 600, '6f cầu đang quay 1× được tăng tốc');
446	    await until(() => window.__app.songHan.ctrl.state === 'CLOSED', '6f cầu đóng xong');
447	    check('console sạch (mục 6)', G.errors.length === 0);
448	    await G.page.close();
449	
450	    // 6e: ban đêm nhưng không bay dù
451	    const O = await openApp(browser, srv.url);
452	    await frames(O.page, 3);
453	    await O.page.evaluate(() => { const a = window.__app; a.explore.nightShows.enabled = true; a.dayNight.target = 1; });
454	    await frames(O.page, 20);
455	    const o = await O.page.evaluate(() => { const a = window.__app; return { on: a.explore.nightShows.show.on, state: a.songHan.ctrl.state }; });
456	    check('6e không bay dù: không tự chạy', !o.on && o.state === 'CLOSED');
457	    await O.page.close();
458	
459	    // 6g: cầu đã quay (camera theo dõi đã lưu vị trí) trước khi vào dù; lúc cầu đóng không được kéo camera
460	    const J = await openApp(browser, srv.url);
461	    await frames(J.page, 3);
462	    await J.page.evaluate(() => {
463	      const a = window.__app, n = a.exFlight.CONFIG_explore.nightShows;
464	      n.swingSpeed = 600; a.songHan.ctrl.start(1); a.explore.start(); a.explore.nightShows.enabled = true;
465	      window.__closed = false; a.songHan.ctrl.addEventListener('swingClosed', () => { window.__closed = true; });
466	    });
467	    await J.page.waitForFunction(() => window.__closed, { timeout: 120000 });
468	    await frames(J.page, 3);
469	    check('6g cầu quay trước khi vào dù: đóng xong vẫn ở glider', await J.page.evaluate(() => window.__app.cam.mode === 'glider'));
470	    await J.page.close();
471	  }
472	
473	  // Mục 7 — lịch 23:00 không chạy khi bay dù (bộ tự chạy tắt do ?test)
474	  {
475	    const S = await openApp(browser, srv.url + '?explore=glider');
476	    await frames(S.page, 3);
477	    await S.page.evaluate(() => { const t = Date.UTC(2026, 10, 7, 16, 2, 0); Date.now = () => t; });   // 23:02 thứ Bảy giờ Việt Nam
478	    await new Promise((r) => setTimeout(r, 21000));
479	    check('7 lịch 23:00 không quay cầu khi bay dù', await S.page.evaluate(() => window.__app.songHan.ctrl.state === 'CLOSED'));
480	    await S.page.close();
481	  }
482	} catch (e) {
483	  problems.push('ngoại lệ: ' + e); console.log(e);
484	} finally {
485	  await browser.close(); srv.close();
486	}
487	console.log(problems.length ? `explore-check: LỖI (${problems.length}): ${problems.join('; ')}` : 'explore-check: đạt');
488	process.exit(problems.length ? 1 : 0);
